// Modular-Trackular mods. SPDX-License-Identifier: MIT
//
// The Master FX default pack, as the firmware carries it (masterfxPack.inc, generated by
// tools/masterfx/build_pack.py --embed from masterfx-sdk/pack/). Written to /MasterFX/ for each
// file that is missing there, or that is a file an earlier release shipped (masterfxPlugins.cpp).
// In flash.

#include "modsBuild.h"

#if MT_HAS_MASTERFX

#include "masterfxPlugins.h"

namespace mods
{
namespace masterfx
{
namespace plugins
{

namespace
{
#include "masterfxPack.inc"
} // namespace

size_t packCount()
{
    return sizeof(kPack) / sizeof(kPack[0]);
}

const PackFile& packAt(size_t index)
{
    return kPack[index < packCount() ? index : 0];
}

#ifdef MT_HOST_TEST
namespace
{
const ShippedFile* testShipped = nullptr;
size_t testShippedCount = 0;
} // namespace

void shippedForTests(const ShippedFile* list, size_t count)
{
    testShipped = list;
    testShippedCount = count;
}
#endif

size_t shippedCount()
{
#ifdef MT_HOST_TEST
    if (testShipped != nullptr)
    {
        return testShippedCount;
    }
#endif
    return sizeof(kShipped) / sizeof(kShipped[0]);
}

const ShippedFile& shippedAt(size_t index)
{
#ifdef MT_HOST_TEST
    if (testShipped != nullptr)
    {
        return testShipped[index < testShippedCount ? index : 0];
    }
#endif
    return kShipped[index < sizeof(kShipped) / sizeof(kShipped[0]) ? index : 0];
}

uint32_t fileHash(const uint8_t* data, uint32_t size)
{
    uint32_t h = 2166136261u;
    for (uint32_t i = 0; i < size; i++)
    {
        h = (h ^ data[i]) * 16777619u;
    }
    return h;
}

} // namespace plugins
} // namespace masterfx
} // namespace mods

#endif // MT_HAS_MASTERFX
